//! 🎟️ The genuine caller's current loan admits one actual native probe and refuses a second without renewing authority.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[test]
fn native_work_recipient_uses_actual_current_caller_loan_and_posts_once(){
 let row:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("case.schema.json")).unwrap();for(k,v)in row.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}
 for reported in row["reportedWork"].as_array().unwrap(){let reported=reported.as_u64().unwrap();let bytes:Vec<u8>=serde_json::from_value(row["probe"].clone()).unwrap();let stock=super::transport_tests::bank();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7679),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:0});let mut ready=false;for _ in 0..64{if caller.turn(stock,|cx|source.admit_step(cx)).unwrap(){ready=true;break}}assert!(ready);
 caller.turn(stock,|cx|cx.with_original_work_loan(row["currentWork"].as_u64().unwrap(),10000,|cx|{
  let before=cx.original_work_units_spent();let mut callback=|_|true;let mut control=NativeDecodeControl::new(0,&mut callback);let ((valid,work),heap)=observe(||{
   let borrowed=ActualTurn::new(cx);let mut recipient=ActualWork{turn:&borrowed,closing:false};let mut work_loan=source.work_issuer.as_mut().unwrap().loan(&mut recipient);
   let valid=control.with_work_recipient(&mut work_loan,|control|{assert!(control.prepare_work(1)?);let valid=std::str::from_utf8(&bytes).is_ok();control.commit_work(1)?;assert_eq!(control.prepare_work(1)?,row["nextWorkAdmitted"].as_bool().unwrap());Ok::<_,ValueError>(valid)}).unwrap();(valid,control.actual_work())
  });assert!(!heap.overflowed);assert_eq!([heap.requested_bytes,heap.released_bytes],[0,0]);assert_eq!(valid,row["expectedValid"].as_bool().unwrap());assert_eq!(work,row["expectedWork"].as_u64().unwrap());assert_eq!(cx.original_work_units_spent(),before);let supplied=cx.retained_grant();let received=OriginalNativeDecodeSource::receive_observed_work(cx,supplied,cx.fuel_remaining(),OriginalNativeDecodeIssued::<(),ValueError>{value:Err(ValueError::literal(ValueRefusalKind::InvalidValue,"actual native UTF-8 probe rejected its input")),grant:supplied,progress:Default::default(),work:reported},work);assert_eq!(received.reported_work,reported);assert_eq!(received.observed_native_work,work);assert_eq!(received.work,work);assert_eq!(received.value.unwrap_err().message.as_ref(),"actual native UTF-8 probe rejected its input");assert_eq!(received.receiving_refusal.is_some(),reported<work);if let Some(error)=received.receiving_refusal{assert_eq!(error.primary.message(),row["underreportRefusal"].as_str().unwrap());}assert_eq!(cx.original_work_units_spent()-before,u128::from(work));Ok(())
 })).unwrap();for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);}
}

#[test]
fn original_job_decoder_cancels_an_unborn_allocation(){
 let stock=super::transport_tests::bank();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7680),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});
 let mut ready=false;for _ in 0..64{if caller.turn(stock,|cx|source.admit_step(cx)).unwrap(){ready=true;break}}assert!(ready);
 let mut actual=None;let mut unwind=None;let mut allocation=None;let received=caller.turn(stock,|cx|source.receive_step(cx,|control,grant|{assert!(control.prepare_work(1).unwrap());allocation=Some(control.allocate_effect(16,&mut actual,&mut unwind,&mut |_|Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture left backing unborn"))));control.cancel_work().unwrap();OriginalNativeDecodeIssued::<(),ValueError>{value:Ok(()),grant,progress:Default::default(),work:0}})).unwrap().unwrap();
 assert!(received.value.is_ok());assert!(received.receiving_refusal.is_none());assert_eq!((received.work,received.observed_native_work),(0,0));assert!(actual.is_none());assert!(unwind.is_none());let allocation=allocation.take().unwrap();assert!(allocation.quote_refusal.is_none());assert!(allocation.primary.is_some());assert!(allocation.settlement_refusal.is_none());assert_eq!(source.owned_bytes(),Some(0));
 let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::retain(allocation);for _ in 0..65536{if owner.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|{let demand=owner.selected_demand(stock.maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=owner.step(grant);semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())})).unwrap()}assert!(owner.terminal_is_empty());
 for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);
}

#[test]
fn original_job_decoder_posts_actual_allocated_backing(){
 let stock=super::transport_tests::bank();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7681),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});let mut ready=false;
 for _ in 0..64{if caller.turn(stock,|cx|source.admit_step(cx)).unwrap(){ready=true;break}}assert!(ready);let mut bytes=None;let mut actual=None;let mut unwind=None;let mut allocation=None;
 let(received,heap)=observe(||caller.turn(stock,|cx|source.receive_step(cx,|control,grant|{assert!(control.prepare_work(1).unwrap());allocation=Some(control.allocate_effect(16,&mut actual,&mut unwind,&mut |actual|{let mut value=Vec::<u8>::new();value.try_reserve_exact(16).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))?;let capacity=value.capacity();bytes=Some(value);*actual=Some(capacity);Ok(())}));control.commit_work(1).unwrap();OriginalNativeDecodeIssued::<(),ValueError>{value:Ok(()),grant,progress:RetainedCloneProgress{copied_items:1,retained_capacity_bytes:actual.unwrap_or(0),..Default::default()},work:1}})).unwrap().unwrap());
 assert!(received.value.is_ok());assert!(received.receiving_refusal.is_none());assert_eq!((received.work,received.observed_native_work),(1,1));let allocation=allocation.take().unwrap();assert!(allocation.quote_refusal.is_none());assert!(allocation.primary.is_none());assert!(allocation.extent_refusal.is_none());assert!(allocation.settlement_refusal.is_none());assert!(unwind.is_none());assert_eq!(actual,Some(bytes.as_ref().unwrap().capacity()));assert_eq!(heap.requested_bytes,actual.unwrap());assert_eq!(caller.receipt().retained_capacity_bytes,actual.unwrap());assert_eq!(source.owned_bytes(),actual);
 let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::retain(bytes.take().unwrap());for _ in 0..65536{if owner.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|{let demand=owner.selected_demand(stock.maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=owner.step(grant);semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())})).unwrap()}assert!(owner.terminal_is_empty());
 for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);
}

#[test]
fn original_job_decoder_retains_allocation_post_refusal(){
 let stock=super::transport_tests::bank();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7682),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});let mut ready=false;for _ in 0..64{if caller.turn(stock,|cx|source.admit_step(cx)).unwrap(){ready=true;break}}assert!(ready);let cancel=caller.admit_alias(stock);let mut bytes=None;let mut actual=None;let mut unwind=None;let mut allocation=None;
 let(received,heap)=observe(||caller.turn(stock,|cx|source.receive_step(cx,|control,grant|{assert!(control.prepare_work(1).unwrap());allocation=Some(control.allocate_effect(16,&mut actual,&mut unwind,&mut |actual|{let mut value=Vec::<u8>::new();value.try_reserve_exact(16).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))?;let capacity=value.capacity();bytes=Some(value);*actual=Some(capacity);cancel.cancel_now();Ok(())}));control.commit_work(1).unwrap();OriginalNativeDecodeIssued::<(),ValueError>{value:Ok(()),grant,progress:RetainedCloneProgress{copied_items:1,retained_capacity_bytes:actual.unwrap_or(0),..Default::default()},work:1}})).unwrap().unwrap());
 assert!(received.value.is_ok());assert!(received.receiving_refusal.is_none());assert_eq!((received.work,received.observed_native_work),(1,1));let allocation=allocation.take().unwrap();assert!(allocation.quote_refusal.is_none());assert!(allocation.primary.is_none());assert_eq!(allocation.settlement_refusal.as_ref().unwrap().kind,ValueRefusalKind::Canceled);assert!(unwind.is_none());assert_eq!(actual,Some(bytes.as_ref().unwrap().capacity()));assert_eq!(heap.requested_bytes,actual.unwrap());assert_eq!(caller.receipt().retained_capacity_bytes,actual.unwrap());assert_eq!(source.owned_bytes(),actual);
 let mut failure=semio_framework_value::retirement::controlled::ControlledRetirement::retain(allocation);for _ in 0..65536{if failure.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|{let demand=failure.selected_demand(stock.maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=failure.step(grant);semio_framework_value::RetainedWorkOutcome{result,work:failure.last_turn_work()}})?;Ok(())})).unwrap()}assert!(failure.terminal_is_empty());
 let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::retain(bytes.take().unwrap());for _ in 0..65536{if owner.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|{let demand=owner.selected_demand(stock.maximum_copy_bytes)?;semio_framework_job::close_original_retained_step(cx,demand,|grant|{let result=owner.step(grant);semio_framework_value::RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())})).unwrap()}assert!(owner.terminal_is_empty());for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.return_alias(cancel,stock);caller.retire(stock);
}

#[test]
fn original_job_decoder_issuer_requires_its_actual_fresh_metadata_grant(){
 let stock=super::transport_tests::bank();let bytes=NativeDecodeAllocationIssuer::birth_bytes();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7683),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});for _ in 0..32{if source.source.is_some(){break}caller.turn(stock,|cx|source.admit_step(cx)).unwrap();}assert!(source.source.is_some());assert!(source.allocation_issuer.is_none());
 let denied=RetainedCloneGrant{maximum_copy_bytes:bytes-1,..stock};assert!(!caller.turn(denied,|cx|source.admit_step(cx)).unwrap());assert!(source.allocation_issuer.is_none());assert_eq!(caller.receipt().copied_items,0);let exact=RetainedCloneGrant{maximum_copy_bytes:bytes,..stock};assert!(!caller.turn(exact,|cx|source.admit_step(cx)).unwrap());assert!(source.allocation_issuer.is_some());assert_eq!(caller.receipt().copied_items,1);assert_eq!(caller.receipt().copied_bytes,bytes);let work_bytes=OriginalWorkActionIssuer::birth_bytes();let denied_work=RetainedCloneGrant{maximum_copy_bytes:work_bytes-1,..stock};assert!(!caller.turn(denied_work,|cx|source.admit_step(cx)).unwrap());assert!(source.work_issuer.is_none());assert_eq!(caller.receipt().copied_items,0);let exact_work=RetainedCloneGrant{maximum_copy_bytes:work_bytes,..stock};assert!(!caller.turn(exact_work,|cx|source.admit_step(cx)).unwrap());assert!(source.work_issuer.is_some());assert_eq!(caller.receipt().copied_items,1);assert_eq!(caller.receipt().copied_bytes,work_bytes);
 for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);
}

#[test]
fn native_work_reservation_resumes_with_the_original_source_issuer(){
 let law:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let work=law["rebindWork"].as_u64().unwrap();
 let stock=super::transport_tests::bank();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7681),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});
 for _ in 0..64{if caller.turn(stock,|cx|source.admit_step(cx)).unwrap(){break}}assert!(source.receipt.is_some());
 let before=caller.fuel_remaining();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||caller.turn(stock,|cx|source.receive_step(cx,|control,_|->OriginalNativeDecodeIssued<(),ValueError>{assert!(control.prepare_work(work).unwrap());panic!("original reservation interruption")}))));assert!(interrupted.is_err());assert_eq!(caller.fuel_remaining(),before);assert!(source.receipt.as_ref().unwrap().has_pending_work());
 let refusal=caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap_err();assert_eq!(refusal.primary.message(),law["pendingCloseRefusal"].as_str().unwrap());assert!(!source.closing);assert!(source.receipt.as_ref().unwrap().has_pending_work());
 let mut foreign=OriginalJobFixtureCaller::admit(OperationId(7682),Generation(3),stock,||Some(0),1000000,10000);let foreign_result=foreign.turn(stock,|cx|source.receive_step(cx,|_,_|->OriginalNativeDecodeIssued<(),ValueError>{panic!("foreign source advanced original work")}));assert_eq!(foreign_result.is_err(),law["foreignSourceRefused"].as_bool().unwrap());assert!(source.receipt.as_ref().unwrap().has_pending_work());foreign.retire(stock);
 let second=caller.turn(stock,|cx|source.receive_step(cx,|control,grant|{control.commit_work(work).unwrap();OriginalNativeDecodeIssued::<(),ValueError>{value:Ok(()),grant,progress:Default::default(),work}})).unwrap().unwrap();assert!(second.value.is_ok());assert!(second.receiving_refusal.is_none());assert_eq!((second.work,second.observed_native_work),(work,work));
 for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);
}

#[test]
fn native_work_committed_before_unwind_is_charged_once(){
 let law:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let work=law["unwindPaidWork"].as_u64().unwrap();let stock=super::transport_tests::bank();
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(7684),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});
 for _ in 0..64{if caller.turn(stock,|cx|source.admit_step(cx)).unwrap(){break}}assert!(source.receipt.is_some());let before=caller.fuel_remaining();
 let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||caller.turn(stock,|cx|source.receive_step(cx,|control,_|->OriginalNativeDecodeIssued<(),ValueError>{assert!(control.prepare_work(work).unwrap());control.commit_work(work).unwrap();panic!("committed original work interruption")}))));
 assert!(interrupted.is_err());assert_eq!(before-caller.fuel_remaining(),work);assert!(!source.receipt.as_ref().unwrap().has_pending_work());
 for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);
}

#[test]
fn original_job_work_issuer_requires_its_own_paid_birth(){
 let stock=super::transport_tests::bank();let mut caller=OriginalJobFixtureCaller::admit(OperationId(7685),Generation(3),stock,||Some(0),1000000,10000);let mut source=OriginalNativeDecodeSource::empty(OriginalNativeDecodePolicy{maximum_owned_bytes:16});
 for _ in 0..64{if source.issuer_admitted{break}caller.turn(stock,|cx|source.admit_step(cx)).unwrap();}assert!(source.issuer_admitted);assert!(source.work_issuer.is_none());
 let bytes=std::mem::size_of::<OriginalWorkActionIssuer>();let denied=RetainedCloneGrant{maximum_copy_bytes:bytes-1,..stock};let before=caller.fuel_remaining();assert!(!caller.turn(denied,|cx|source.admit_step(cx)).unwrap());assert!(source.work_issuer.is_none());assert_eq!(caller.fuel_remaining(),before);assert_eq!(caller.receipt(),RetainedCloneProgress::default());
 let exact=RetainedCloneGrant{maximum_copy_bytes:bytes,..stock};assert!(!caller.turn(exact,|cx|source.admit_step(cx)).unwrap());assert!(source.work_issuer.is_some());assert_eq!(before-caller.fuel_remaining(),1);assert_eq!(caller.receipt().copied_bytes,bytes);
 for _ in 0..65536{if source.terminal_is_empty(){break}caller.turn(stock,|cx|cx.with_original_retirement(|cx|source.close_step(cx).map(|_|()))).unwrap()}assert!(source.terminal_is_empty());caller.retire(stock);
}
